#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    long double D;
    cin >> N >> D;

    vector<long double> P(N + 1), C(N + 1);
    for (int i = 0; i < N; ++i) {
        cin >> P[i] >> C[i];
    }
    P[N] = D;

    const long double INF = numeric_limits<long double>::infinity();
    vector<long double> dp(N + 1, INF);
    dp[0] = 0;

    for (int j = 1; j <= N; ++j) {
        for (int i = 0; i < j; ++i) {
            long double dist = P[j] - P[i];
            dp[j] = min(dp[j], dp[i] + dist * dist / C[i]);
        }
    }

    cout << fixed << setprecision(3) << dp[N] << '\n';
    return 0;
}
